from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse right
            for j in range(len(grid[i])):
                result.append(grid[i][j])
        else:
            # Traverse left
            for j in range(len(grid[i]) - 1, -1, -1):
                result.append(grid[i][j])
    return [result[k] for k in range(len(result)) if k % 2 == 0]

def findValidPair(s: str) -> str:
    from collections import Counter

    # Count occurrences of each digit
    counts = Counter(s)

    # Iterate through the string to find valid pairs
    for i in range(len(s) - 1):
        first_digit = s[i]
        second_digit = s[i + 1]
        # Check if they are not equal and both counts are valid
        if first_digit != second_digit:
            if counts[first_digit] == int(first_digit) and counts[second_digit] == int(second_digit):
                return first_digit + second_digit
    return ""

