def sumOfGoodNumbers(nums: List[int], k: int) -> int:
    total = 0
    n = len(nums)
    for i in range(n):
        is_good = True
        if i - k >= 0 and nums[i] <= nums[i - k]:
            is_good = False
        if i + k < n and nums[i] <= nums[i + k]:
            is_good = False
        if is_good:
            total += nums[i]
    return total

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == 1:  # Check if all characters are the same
            # Check preceding character
            if i > 0 and s[i - 1] == substring[0]:
                continue
            # Check following character
            if i + k < n and s[i + k] == substring[0]:
                continue
            return True
    return False

def hasSameDigits(s: str) -> bool:
    while len(s) > 2:
        s = ''.join(str((int(s[i]) + int(s[i + 1])) % 10) for i in range(len(s) - 1))
    return s[0] == s[1]

