from itertools import permutations

def totalNumbers(digits: List[int]) -> int:
    found_numbers = set()
    # Using set(permutations(...)) correctly handles duplicate digits by
    # producing only unique 3-element permutations.
    for p in set(permutations(digits, 3)):
        # A 3-digit number cannot start with 0.
        if p[0] == 0:
            continue
        # The number must be even.
        if p[2] % 2 == 0:
            found_numbers.add(p)
    return len(found_numbers)

def maxContainers(n: int, w: int, maxWeight: int) -> int:
    deck_capacity = n * n
    weight_capacity = maxWeight // w
    return min(deck_capacity, weight_capacity)

def reverseDegree(s: str) -> int:
    reverse_alphabet_value = {chr(i + 96): 27 - i for i in range(1, 27)}
    total = 0
    for index, char in enumerate(s):
        position_in_string = index + 1  # 1-indexed
        reverse_value = reverse_alphabet_value[char]
        total += reverse_value * position_in_string
    return total

