def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    # dp[i] will hold the length of the longest subsequence ending at index i
    dp = [1] * n

    # Iterate through each combination of indices to find the longest subsequence
    for i in range(n):
        for j in range(i):
            # Calculate the absolute difference
            diff1 = abs(nums[i] - nums[j])
            # Check possible previous indices for non-increasing differences
            for k in range(j):
                diff2 = abs(nums[j] - nums[k])
                # Ensure the absolute differences are non-increasing
                if diff1 <= diff2:
                    dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

