def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # dp[i][j][k] will hold the maximum coins that can be collected to reach (i, j) with k neutralizations used
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0] if coins[0][0] >= 0 else 0  # Starting point

    for i in range(m):
        for j in range(n):
            for k in range(3):
                if i == 0 and j == 0:
                    continue  # Skip the starting cell

                current_coins = coins[i][j]
                # Calculate maximum coins arriving at (i, j)
                if i > 0:
                    # Moving from above
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k])
                if j > 0:
                    # Moving from the left
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k])

                if current_coins >= 0:
                    dp[i][j][k] += current_coins  # Collect coins
                else:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j][k-1])  # Neutralize the robber
                    else:
                        dp[i][j][k] += current_coins  # Take the loss

    result = max(dp[m-1][n-1][0], dp[m-1][n-1][1], dp[m-1][n-1][2])
    return result

