def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]

    # Initialize the first house costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    for i in range(1, n):
        for j in range(3):
            # For the current house, calculate the minimum cost for each color
            dp[i][j] = cost[i][j] + min(
                dp[i-1][(j+1) % 3],  # Not the same as previous house
                dp[i-1][(j+2) % 3]   # Not the same as previous house
            )

    # To ensure equidistant condition, we need to track last house's equivalent colors
    minimum_cost = float('inf')
    for j in range(3):
        total_cost = dp[n-1][j]
        # We cannot have the same color as its symmetric counterpart
        for k in range(3):
            if (j + k) % 3 != 0:
                total_cost = min(total_cost, dp[n // 2 - 1][k] + dp[n - 1][j])
        minimum_cost = min(minimum_cost, total_cost)

    return minimum_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_till = [0] * numberOfUsers

    # Sort events by timestamp and prioritize OFFLINE over MESSAGE at the same timestamp.
    events.sort(key=lambda x: (int(x[1]), x[0] == 'MESSAGE'))

    for event in events:
        event_type, timestamp, *details = event
        timestamp = int(timestamp)

        # Update online status before processing MESSAGE events
        for user_id in range(numberOfUsers):
            if not online_status[user_id] and timestamp >= offline_till[user_id]:
                online_status[user_id] = True

        if event_type == "OFFLINE":
            user_id = int(details[0])
            online_status[user_id] = False
            offline_till[user_id] = timestamp + 60
        elif event_type == "MESSAGE":
            mentions_string = details[0]
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                user_ids = mentions_string.split()
                for user_id_str in user_ids:
                    if user_id_str.startswith("id"):
                        user_id = int(user_id_str[2:])
                        mentions[user_id] += 1  # Count mentions regardless of online status

    return mentions

